{
  "title": "迷失的轨道",
  "scene": "你漂流在宇宙的黑暗中，飞船的能源即将耗尽。突然，一块巨大的太空碎片出现在你的前方，阻挡了你唯一的逃生路径。你必须做出选择，否则飞船将会在撞击中爆炸，你和飞船内的所有物资都将化为尘埃。",
  "goal": "找到绕过太空碎片的方法，或者破坏它以打开逃生路径。",
  "choices": [
    {
      "id": "A",
      "text": "尝试用激光切割太空碎片",
      "outcome": "你的激光正好穿透了太空碎片的一个薄弱点，碎片开始裂开，但未能完全破碎，碎片碎片朝你的方向飞来，险象环生。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "使用推进器尝试强行穿过碎片缝隙",
      "outcome": "飞船勉强穿过缝隙，但螺旋桨受损严重，飞船摇摇欲坠，系统的警报声不绝于耳。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "寻找太空碎片周围的小行星，使用引力改变飞船航向绕过碎片",
      "outcome": "经过数分钟的搜索，你找到了一个合适的小行星，成功改变了飞船的航向，避免了撞击，但飞船的燃料储备已经减少到5%。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
